<script setup lang="ts">
import {adsToday} from './adsDates'
import {useTableWidths} from './tableWidths'
const tableWidths=useTableWidths('DashboardPanel')

import {ref,computed,onMounted,onUnmounted,watch} from 'vue'
import {ElMessage} from 'element-plus'
import {api} from './session'
import {displayCurrency as currency} from './currency'
const props=withDefaults(defineProps<{store:string,visible?:boolean}>(),{visible:true}),emit=defineEmits<{navigate:[value:string]}>()
const data=ref<any>(null),busy=ref(false),error=ref(''),trend=ref('7'),market=ref(''),hover=ref<number|null>(null)
const periods=[['today','今日'],['yesterday','昨日'],['7','近7日'],['14','近14日'],['30','近30日']]
const chartBusy=ref(false),chart=ref<any>(null),todayBest=ref<any>({rows:[],total:0}),bestPage=ref(1)
const storeBest=ref<any>({rows:[]}),bestPeriod=ref('30'),bestQuery=ref(''),storeBestBusy=ref(false)
let bestSeq=0,todayBestSeq=0
async function loadStoreBest(){const id=++bestSeq;storeBestBusy.value=true;try{const d=await api('/dashboard/store-best?'+new URLSearchParams({store:props.store,marketplace:market.value,period:bestPeriod.value,q:bestQuery.value}));if(id===bestSeq)storeBest.value=d}catch(e){if(id===bestSeq)ElMessage.error((e as Error).message)}finally{if(id===bestSeq)storeBestBusy.value=false}}
const chartDay=adsToday
let visibleChartDay=chartDay(),dayTimer:ReturnType<typeof setInterval>|undefined
function refreshChartDay(){if(props.visible&&!document.hidden&&visibleChartDay!==chartDay()){visibleChartDay=chartDay();void loadChart(true)}}
const chartCache=new Map<string,any>();let chartSeq=0
async function loadChart(force=false){visibleChartDay=chartDay();const id=++chartSeq;const key=[props.store,market.value,trend.value,currency.value].join('|');if(!force&&chartCache.has(key)&&chartCache.get(key).day===chartDay()&&Date.now()-chartCache.get(key).at<300000){chart.value=chartCache.get(key).data;chartBusy.value=false;return}chartBusy.value=true;try{const d=await api('/dashboard/trend?'+new URLSearchParams({store:props.store,marketplace:market.value,trend:trend.value,currency:currency.value}));chartCache.set(key,{data:d,at:Date.now(),day:chartDay()});if(id===chartSeq)chart.value=d}catch(e){ElMessage.error((e as Error).message)}finally{if(id===chartSeq)chartBusy.value=false}}
async function loadBest(){const id=++todayBestSeq;try{const d=await api('/dashboard/today-best?page='+bestPage.value);if(id===todayBestSeq)todayBest.value=d}catch(e){if(id===todayBestSeq)ElMessage.error((e as Error).message)}}
const shownPeriods=computed(()=>periods.filter(([k])=>data.value?.cards[k!]))
const trends=[['7','7天'],['14','14天'],['30','30天'],['6m','半年'],['1y','一年']]
const series=[{key:'units',label:'销量',color:'#269ff2'},{key:'ad_spend',label:'广告花费',color:'#ff7895'},{key:'acos',label:'ACOS',color:'#91d86b'}]
const fmt=(n:any)=>n==null?'—':Number(n).toLocaleString('zh-CN',{maximumFractionDigits:2})
const money=(a:any,c:string)=>a==null?'—':new Intl.NumberFormat('zh-CN',{style:'currency',currency:c}).format(Number(a))
let seq=0,timer:ReturnType<typeof setTimeout>|undefined
async function syncStock(){try{await api('/dashboard/inventory/refresh',{store:props.store});ElMessage.success('全店库存已加入后台同步');await load()}catch(e){ElMessage.error((e as Error).message)}}
async function load(background=false,refresh=false){
 if(!props.visible)return
 void loadChart(refresh);void loadBest();void loadStoreBest();const id=++seq;if(timer)clearTimeout(timer)
 if(!background){busy.value=true;hover.value=null}
 localStorage.setItem('erp-home-currency',currency.value)
 try{const p=new URLSearchParams({store:props.store,marketplace:market.value,trend:trend.value,currency:currency.value});if(refresh)p.set('refresh','true');const d=await api('/dashboard?'+p)
  if(id===seq){if(JSON.stringify(data.value)!==JSON.stringify(d))data.value=d;error.value=''}
 }catch(e){if(id===seq)error.value=(e as Error).message}
 finally{if(id===seq){busy.value=false;if(props.visible&&(['queued','running'].includes(data.value?.inventory?.sync_status)||data.value?.history_cache?.stale))timer=setTimeout(()=>load(true),8000)}}
}
const points=computed<any[]>(()=>chart.value?.trend.points||[])
const maxima=computed<Record<string,number>>(()=>Object.fromEntries(series.map(s=>[s.key,Math.max(s.key==='acos'?100:1,...points.value.map(p=>Number(p[s.key]||0)))])))
const x=(i:number)=>60+i*850/Math.max(1,points.value.length-1)
const y=(p:any,k:string)=>210-Number(p[k])/maxima.value[k]!*180
function line(key:string){let path='',active=false;points.value.forEach((p,i)=>{if(p[key]==null){active=false;return}path+=`${active?'L':'M'}${x(i)},${y(p,key)} `;active=true});return path}
const labels=computed(()=>points.value.map((p,i)=>({label:chart.value?.trend.monthly?p.label:p.label.slice(5),i})).filter((_,i)=>i%Math.max(1,Math.ceil(points.value.length/9))===0||i===points.value.length-1))
const active=computed(()=>hover.value==null?null:points.value[hover.value])
const tooltipTitle=computed(()=>{if(!active.value)return '';const label=active.value.label;if(chart.value?.trend.monthly)return label+' 月汇总';return label+'（'+['周日','周一','周二','周三','周四','周五','周六'][new Date(label+'T12:00:00').getDay()]+'）'})
function pointer(e:PointerEvent){const rect=(e.currentTarget as SVGElement).getBoundingClientRect();const px=(e.clientX-rect.left)/rect.width*1000;hover.value=Math.max(0,Math.min(points.value.length-1,Math.round((px-60)/850*Math.max(1,points.value.length-1))))}
function keydown(e:KeyboardEvent){if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();hover.value=Math.max(0,Math.min(points.value.length-1,(hover.value??0)+(e.key==='ArrowRight'?1:-1)))}}
const percent=(v:any)=>v==null?'—':(Number(v)>0?'+':'')+fmt(v)+'%'
const pie=computed(()=>{const t=data.value?.inventory.totals;if(!t||t.total==null||!t.total)return '#edf1ef';return `conic-gradient(#248674 0 ${t.in_stock/t.total*100}%, #87b9f5 0 100%)`})
onMounted(()=>{load();dayTimer=setInterval(refreshChartDay,15000);document.addEventListener('visibilitychange',refreshChartDay);window.addEventListener('focus',refreshChartDay)});onUnmounted(()=>{clearInterval(dayTimer);document.removeEventListener('visibilitychange',refreshChartDay);window.removeEventListener('focus',refreshChartDay);seq++;chartSeq++;bestSeq++;todayBestSeq++;if(timer)clearTimeout(timer)});watch(()=>props.store,()=>load());watch(()=>props.visible,visible=>{if(visible)load(!!data.value);else{seq++;busy.value=false;if(timer)clearTimeout(timer)}})
</script>
<template><div v-loading="busy"><div class="dashboard-toolbar"><span>{{store}} · 经营概览</span><div><el-select v-model="market" placeholder="全部站点" clearable style="width:145px" @change="load()"><el-option v-for="(name,m) in {UK:'英国',DE:'德国',FR:'法国',ES:'西班牙',IT:'意大利',BE:'比利时',NL:'荷兰',PL:'波兰',SE:'瑞典',IE:'爱尔兰',AE:'阿联酋',SA:'沙特'}" :key="m" :label="name" :value="m"/></el-select><el-select v-model="currency" aria-label="展示币种" style="width:150px" @change="load()"><el-option label="英镑 GBP" value="GBP"/><el-option label="欧元 EUR" value="EUR"/><el-option label="人民币 CNY" value="CNY"/></el-select><el-button @click="load(false,true)">刷新概览</el-button></div></div><el-alert v-if="error" :title="error" type="error" :closable="false"/>
<template v-if="data"><div class="dashboard-sales"><article v-for="[key,title] in shownPeriods" :key="key" class="stat-card overview-card"><div class="overview-title"><h2>{{title}}</h2><el-tag v-if="!data.cards[key].complete" type="info" size="small">已入库部分</el-tag></div><div class="sales-primary"><div><span>销量</span><strong>{{fmt(data.cards[key].units)}}<small>件</small></strong></div><div><span>销售额</span><strong>{{money(data.cards[key].converted.amount,data.fx.currency)}}</strong></div></div>
<template v-if="key!=='today'"><div class="profit-metrics"><div><span>结算利润</span><b>{{money(data.cards[key].settlement.amount,data.fx.currency)}}</b></div><div><span>结算毛利</span><b>{{percent(data.cards[key].settlement.margin)}}{{data.cards[key].settlement.margin_partial&&data.cards[key].settlement.margin!==null?'*':''}}</b></div><div><span>订单利润</span><b>{{money(data.cards[key].order_profit.amount,data.fx.currency)}}{{data.cards[key].profit_partial?'*':''}}</b></div><div><span>订单毛利</span><b>{{percent(data.cards[key].order_margin)}}{{data.cards[key].profit_partial?'*':''}}</b></div></div><p class="metrics-note card-note">结算按入账日期的已释放金额；订单按下单日期的预估毛利。近7日、近30日不含今天。<span v-if="data.cards[key].settlement.unknown_sales_orders"> 结算中 {{data.cards[key].settlement.unknown_sales_orders}} 笔销售额待补齐，结算毛利仅按金额和销售额均已知的部分计算。</span><span v-if="data.cards[key].unknown_profit_orders"> 已估算 {{data.cards[key].known_profit_orders}} 笔，{{data.cards[key].unknown_profit_orders}} 笔待补齐；* 为已估算部分，订单毛利按同批已估算订单销售额计算。</span></p></template><div class="stat-foot">{{data.cards[key].orders}} 笔订单<span v-if="data.cards[key].estimated_amount_orders"> · {{data.cards[key].estimated_amount_orders}} 笔售价预估</span><span v-if="data.cards[key].unknown_amount_orders"> · {{data.cards[key].unknown_amount_orders}} 笔金额待返回</span><span v-if="data.cards[key].converted.missing_currencies.length"> · 汇率待补齐</span></div></article></div><p v-if="data.history_cache" class="metrics-note">历史统计：{{data.history_cache.updated_at?new Date(data.history_cache.updated_at).toLocaleString('zh-CN'):'计算中'}}<span v-if="data.history_cache.stale"> · 正在根据已入库数据更新，当前显示上一份缓存</span><span v-if="data.history_cache.error"> · {{data.history_cache.error}}</span></p><p class="metrics-note">{{data.note}} 最近订单读取：{{data.as_of?new Date(data.as_of).toLocaleString('zh-CN'):'尚未同步'}}</p>
<section class="panel trend-panel"><div class="panel-head"><h2>广告概览与业绩走势</h2><el-radio-group v-model="trend" size="small" @change="loadChart()"><el-radio-button v-for="[v,t] in trends" :key="v" :value="v">{{t}}</el-radio-button></el-radio-group></div><div class="ads-grid"><div v-for="[key,title] in periods" :key="key"><span>{{title}}</span><strong>{{money(chart?.ads[key!]?.cost,data.fx.currency)}}</strong><small>销售额 {{money(chart?.ads[key!]?.sales,data.fx.currency)}}</small><small>ACOS {{fmt(chart?.ads[key!]?.acos)}}{{chart?.ads[key!]?.acos==null?'':'%'}}</small><small v-if="chart?.ads[key!]&&!chart.ads[key!].complete">已同步部分</small></div></div><div v-loading="chartBusy"><div class="chart-legend"><span v-for="s in series" :key="s.key"><i :style="{background:s.color}"/>{{s.label}}</span><span class="muted">{{chart?.trend.monthly?'按月汇总':'按日汇总'}} · {{chart?.trend.start}} — {{chart?.trend.end}}</span><span v-if="!chart?.trend.complete" class="muted">含尚未同步的时段，显示已入库数据</span></div>
<div class="trend-interactive"><svg viewBox="0 0 1000 260" role="img" aria-label="业绩走势：销量、广告花费、ACOS；左右方向键切换日期" tabindex="0" class="sales-chart" @pointermove="pointer" @pointerleave="hover=null" @focus="hover=points.length-1" @blur="hover=null" @keydown="keydown"><text x="60" y="16" class="chart-label">销量（件）</text><text x="910" y="16" text-anchor="end" class="chart-label">广告花费（{{data.fx.currency}}） / ACOS（%）</text><g v-for="n in 5" :key="n"><line x1="60" x2="910" :y1="210-(n-1)*45" :y2="210-(n-1)*45" stroke="#e7eeeb" stroke-dasharray="3 5"/><text x="49" :y="214-(n-1)*45" text-anchor="end" class="chart-label">{{fmt(maxima.units!*(n-1)/4)}}</text></g><path v-for="s in series" :key="s.key" :d="line(s.key)" :stroke="s.color" fill="none" stroke-width="2.5"/><template v-if="active&&hover!==null"><line :x1="x(hover)" :x2="x(hover)" y1="30" y2="210" stroke="#b9c4d0" stroke-dasharray="4 4"/><template v-for="s in series" :key="s.key"><circle v-if="active[s.key]!=null" :cx="x(hover)" :cy="y(active,s.key)" r="5" :fill="s.color" stroke="white" stroke-width="2"/></template></template><text v-for="l in labels" :key="l.i" :x="x(l.i)" y="244" text-anchor="middle" class="chart-label">{{l.label}}</text></svg>
<div v-if="active&&hover!==null" role="status" class="trend-tooltip" :style="{left:Math.min(72,Math.max(2,x(hover)/10-12))+'%'}"><strong>{{tooltipTitle}}</strong><div v-for="s in series" :key="s.key"><span><i :style="{background:s.color}"/>{{s.label}}</span><b>{{active[s.key]==null?'—':s.key==='ad_spend'?money(active[s.key],data.fx.currency):fmt(active[s.key])+(s.key==='acos'?'%':'')}}</b></div></div></div><p class="metrics-note">近7日、近14日、近30日按北京时间选择截至昨天的日期，不含今天。悬停或使用左右方向键查看当日／当月数据。广告按已同步日报统计，未同步日期显示为空。</p></div></section>
<div class="home-pair stock-and-best"><div class="home-left-stack"><section class="panel inventory-overview"><div class="panel-head"><h2>库存概览</h2><TableReset table-key="DashboardPanel/table-1"/></div><el-alert v-if="data.inventory.sync_error" :title="data.inventory.sync_error" type="warning" :closable="false"/><div class="stock-layout"><div class="stock-ring" :style="{background:pie}"><div><strong>{{fmt(data.inventory.totals.total)}}</strong><small>总库存</small></div></div><div class="stock-headlines"><div><span><i class="stock-dot onhand"/>在库</span><strong>{{fmt(data.inventory.totals.in_stock)}}</strong></div><div><span><i class="stock-dot transit"/>在途</span><strong>{{fmt(data.inventory.totals.shipped)}}</strong></div></div><template v-if="true"><el-table border data-width-key="DashboardPanel/table-1" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-1', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-1', column, event)" :data="data.inventory.groups"><el-table-column :column-key="'column-1'" :width="tableWidths.width('table-1', 'column-1', undefined)" label="库存区域"><template #default="{row}">{{row.region==='UK'?'英国':'欧洲大陆（去重参考）'}}</template></el-table-column><el-table-column :column-key="'column-2:' + (k)" :width="tableWidths.width('table-1', 'column-2:' + (k), undefined)" v-for="[k,label] in [['in_stock','在库'],['shipped','在途'],['total','合计']]" :key="k" :label="label"><template #default="{row}">{{fmt(row[k!])}}</template></el-table-column></el-table></template></div><p class="metrics-note">在库＝FBA可售＋接收中＋仓内处理中；在途＝已发货、尚在运输中的库存。{{data.inventory.note}}</p></section><section class="panel"><div class="panel-head"><h2>绩效与邮件通知</h2><el-tag type="info">待接入</el-tag></div><el-empty description="账户健康、绩效指标及邮件通知将在接入后展示" :image-size="65"/></section></div><section class="panel bestseller-panel store-best"><div class="panel-head"><h2>本店畅销榜</h2><TableReset table-key="DashboardPanel/table-2"/></div><form class="best-filters" @submit.prevent="loadStoreBest"><el-input v-model="bestQuery" placeholder="搜索 SKU / ASIN / 商品" clearable @clear="loadStoreBest"/><el-select v-model="bestPeriod" aria-label="本店畅销榜日期" @change="loadStoreBest"><el-option v-for="[key,label] in [['today','今日'],['yesterday','昨日'],['7','近7日'],['30','近30日']]" :key="key" :value="key" :label="label"/></el-select><el-button native-type="submit">搜索</el-button></form><el-table class="best-table" border data-width-key="DashboardPanel/table-2" @header-dragend="(width:number,_old:number,column:any)=>tableWidths.resize('table-2',width,column)" @header-contextmenu="(column:any,event:MouseEvent)=>tableWidths.resetColumn('table-2',column,event)" :data="storeBest.rows" size="small" v-loading="storeBestBusy">
<el-table-column column-key="rank" label="#" :width="tableWidths.width('table-2','rank',60)" class-name="rank-cell"><template #default="{$index}"><span class="rank-number">{{$index+1}}</span></template></el-table-column>
<el-table-column column-key="product" label="商品" min-width="180" :width="tableWidths.width('table-2','product')"><template #default="{row}"><div class="bestseller-product"><el-image v-if="row.image_url" :src="row.image_url" fit="contain" loading="lazy"/><div><b :title="row.asin">{{row.asin}}</b><small :title="row.title">{{row.title}}</small></div></div></template></el-table-column>
<el-table-column column-key="store" prop="store" label="店铺" :width="tableWidths.width('table-2','store',100)"/>
<el-table-column column-key="marketplace" prop="marketplace" label="站点" :width="tableWidths.width('table-2','marketplace',70)"/>
<el-table-column column-key="units" prop="units" label="销量" :width="tableWidths.width('table-2','units',75)"/>
<template #empty><el-empty description="暂无符合条件的订单数据" :image-size="50"/></template></el-table></section><section class="panel bestseller-panel today-best"><div class="panel-head"><h2>今日畅销榜</h2><span class="muted">全部店铺 · 单站点ASIN · 前100名</span><TableReset table-key="DashboardPanel/table-3"/></div><el-table class="best-table" border data-width-key="DashboardPanel/table-3" @header-dragend="(width:number,_old:number,column:any)=>tableWidths.resize('table-3',width,column)" @header-contextmenu="(column:any,event:MouseEvent)=>tableWidths.resetColumn('table-3',column,event)" :data="todayBest.rows" size="small" >
<el-table-column column-key="rank" label="#" :width="tableWidths.width('table-3','rank',60)" class-name="rank-cell"><template #default="{$index}"><span class="rank-number">{{(bestPage-1)*10+$index+1}}</span></template></el-table-column>
<el-table-column column-key="product" label="商品" min-width="180" :width="tableWidths.width('table-3','product')"><template #default="{row}"><div class="bestseller-product"><el-image v-if="row.image_url" :src="row.image_url" fit="contain" loading="lazy"/><div><b :title="row.asin">{{row.asin}}</b><small :title="row.title">{{row.title}}</small></div></div></template></el-table-column>
<el-table-column column-key="store" prop="store" label="店铺" :width="tableWidths.width('table-3','store',100)"/>
<el-table-column column-key="marketplace" prop="marketplace" label="站点" :width="tableWidths.width('table-3','marketplace',70)"/>
<el-table-column column-key="units" prop="units" label="销量" :width="tableWidths.width('table-3','units',75)"/>
<template #empty><el-empty description="暂无符合条件的订单数据" :image-size="50"/></template></el-table><el-pagination v-model:current-page="bestPage" :page-size="10" :total="todayBest.total" layout="prev,pager,next" small @current-change="loadBest"/></section></div><section class="panel"><div class="panel-head"><h2>系统提醒</h2></div><button class="todo-line" @click="emit('navigate','listing')"><span>商品接口错误</span><b>{{data.todos.listing_errors}} →</b></button><button class="todo-line" @click="emit('navigate','listing')"><span>目录资料待补齐</span><b>{{data.todos.missing_catalog}} →</b></button><div class="todo-line"><span>失败的同步任务</span><b>{{data.todos.failed_syncs}}</b></div><p class="metrics-note">系统异常可通过待办事项分配给负责人跟进。</p></section>
</template></div></template>

<style scoped>.bestseller-panel{min-width:0}.bestseller-panel .panel-head{flex-wrap:wrap;gap:8px}.best-filters{display:flex;flex-wrap:wrap;gap:8px;padding:0 16px 12px}.best-filters .el-input{flex:1;min-width:130px}.best-filters .el-select{width:110px}.rank-number{white-space:nowrap;word-break:keep-all}.best-table :deep(.rank-cell .cell){padding:0 8px;white-space:nowrap;word-break:keep-all;text-overflow:clip}.profit-metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px 16px}.dashboard-sales{grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}.overview-card{padding:16px}.overview-card h2{font-size:17px}.sales-primary{flex-wrap:wrap;gap:10px}.sales-primary strong{font-size:22px}.ads-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin:14px 0}.ads-grid>div{padding:12px}.ads-grid strong{font-size:21px}.ads-grid small{display:block}.stock-and-best{display:grid;grid-template-columns:minmax(280px,1fr) minmax(300px,1fr) minmax(300px,1fr);gap:16px}.stock-layout{flex-wrap:wrap}.bestseller-product{min-width:0}.bestseller-product>div{min-width:0}.bestseller-product small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:190px}.trend-panel{padding:18px}.sales-chart{max-height:260px}@media(max-width:1250px){.dashboard-sales{grid-template-columns:repeat(3,minmax(0,1fr))}.stock-and-best{grid-template-columns:1fr 1fr}.home-left-stack{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr;gap:16px}}@media(max-width:800px){.stock-and-best,.home-left-stack{grid-template-columns:1fr}.dashboard-sales{grid-template-columns:repeat(2,minmax(0,1fr))}} </style>
